<script lang="ts">
 import {page} from '$app/state';
 import {Search,ChevronDown,ArrowLeft,CalendarClock,FileText,ExternalLink,Layers,ShieldCheck,CircleHelp} from 'lucide-svelte';
 import {contractCounts,contractGroups,contractStatusLabels,type ContractItem} from '$lib/ledger-contracts.js';
 import HouseholdEntryEvidence from '$lib/components/ledger/HouseholdEntryEvidence.svelte';
 import '$lib/components/ledger/household.css';
 import type {PageData} from './$types.js';
 let {data}:{data:PageData}=$props();
 let filter=$state('all'),query=$state(''),group=$state(''),expanded=$state(''),bank=$state('');
 const currentNotices=$derived(data.sync?.notices.filter(n=>!n.historical)??[]),historicalNotices=$derived(data.sync?.notices.filter(n=>n.historical)??[]);
 const items=$derived(data.inventory?.items??[]),counts=$derived(contractCounts(items));
 const filters=$derived([{id:'all',label:'Alle',n:counts.all},{id:'high',label:'Zuerst prüfen',n:counts.high},{id:'uncertain',label:'Status offen',n:counts.uncertain},{id:'cancelled',label:'Gekündigt',n:counts.cancelled}]);
 const shown=$derived(items.filter(i=>(filter==='all'||filter==='high'&&i.priority==='high'&&i.status!=='cancelled'||filter===i.status)&&(!group||i.group===group)&&(!query||[i.label,i.summary,i.cost].join(' ').toLocaleLowerCase('de').includes(query.toLocaleLowerCase('de')))));
 const date=(s:string)=>new Date(s+'T12:00:00Z').toLocaleDateString('de-CH',{timeZone:'UTC'});
 const open=(i:ContractItem)=>{expanded=expanded===i.id?'':i.id;bank='';};
 $effect(()=>{const id=page.url.hash.slice(1);if(items.some(i=>i.id===id)){expanded=id;filter='all';query='';group='';}});
</script>
<svelte:head><title>Folio · Abos & Fixkosten</title><meta name="robots" content="noindex, nofollow"/></svelte:head>
<main id="folio-household" class="contracts">
 <div class="content">
  <a class="back" href="/ledger/wealth"><ArrowLeft size={15}/> Haushaltsbuch</a>
  <header><div><p class="eyebrow">LEDGER · VERTRÄGE</p><h1>Abos & Fixkosten</h1><p>Was läuft. Was bald kostet. Was sich prüfen lohnt.</p></div><span class="asof">{#if data.inventory}Geprüft {date(data.inventory.as_of)}{/if}</span></header>
  {#if data.error}<p role="alert">{data.error}</p>{:else if !data.inventory}<p>Noch keine geprüfte Vertragsübersicht vorhanden.</p>{:else}
   <div class="metrics"><button onclick={()=>filter='high'}><CalendarClock size={22}/><strong>{counts.high}</strong><span>zuerst prüfen</span></button><button onclick={()=>filter='all'}><Layers size={22}/><strong>{counts.all}</strong><span>Posten erfasst</span></button><button onclick={()=>filter='uncertain'}><CircleHelp size={22}/><strong>{counts.uncertain}</strong><span>Status offen</span></button><button onclick={()=>filter='cancelled'}><ShieldCheck size={22}/><strong>{counts.cancelled}</strong><span>Kündigung belegt</span></button></div>
   {#if data.stale}<p class="warning" role="status">Quellenstand geändert oder teilweise nicht verfügbar. Die Liste zeigt den letzten Prüfstand; betroffene Belege müssen erneut geprüft werden.</p>{/if}
   <details class="coverage"><summary>Datenstand & Lücken · Konten bis {date(data.inventory.coverage.bank_through)}</summary><p>{data.inventory.coverage.mail_rows.toLocaleString('de-CH')} lokale Maildatensätze, davon {data.inventory.coverage.mail_with_text.toLocaleString('de-CH')} mit Text; {data.inventory.coverage.bank_entries.toLocaleString('de-CH')} Kontobewegungen aus 2026 geprüft.</p><ul>{#each data.inventory.coverage.limitations as note}<li>{note}</li>{/each}</ul><p>Mailquellen: {data.inventory.coverage.accounts.join(', ')}. Eindeutige neue Vertragsmails ergänzen den geprüften Bestand beim Mailimport. Bankzahlungen werden weiterhin getrennt abgeglichen.</p></details>
   {#if data.sync}<details class="coverage"><summary>Mailabgleich {data.sync.enabled?'aktiv':'pausiert'} · {data.sync.profiles}/{data.sync.total} Posten zugeordnet{#if data.sync.report} · geprüft {new Date(data.sync.report.checkedAt).toLocaleString('de-CH')}{/if}</summary><p>Nach jedem Import, vor der Memory-Extraktion. {data.sync.automatic} eindeutig abgegrenzte Posten können automatisch aktualisiert werden; Sammelposten benötigen eine Zuordnung. {data.sync.changed} Posten seit der Bestandsaufnahme ergänzt. Nicht zugeordnete Anbieter und reine Kontoposten bleiben zur Prüfung offen.</p>{#if data.sync.report?.state==='failed'}<p role="alert">Der letzte Abgleich ist fehlgeschlagen. Der Mail-Lauf versucht ihn erneut.</p>{/if}<p>Alte Mails überschreiben keinen neueren Stand. Rechnungen bestätigen keine Kontozahlung. Eine Kündigung wird hier nicht beim Anbieter ausgelöst.</p></details>{/if}
   {#if currentNotices.length}<details class="coverage warning"><summary>{currentNotices.length} Vertragsmails zur Prüfung</summary>{#each currentNotices as notice}<p><strong>{notice.label}</strong> · {notice.reason} <a href={'/mail-queue?feedback='+notice.mailId}>Mail prüfen</a></p>{/each}</details>{/if}
   {#if historicalNotices.length}<details class="coverage"><summary>{historicalNotices.length} ältere Mails ohne sichere Vertragszuordnung</summary><p>Vor der Bestandsaufnahme. Sie verändern keinen aktuellen Vertrag.</p>{#each historicalNotices as notice}<p>{notice.label} · <a href={'/mail-queue?feedback='+notice.mailId}>Mail prüfen</a></p>{/each}</details>{/if}
   <div class="controls"><nav aria-label="Vertragsstatus">{#each filters as f}<button class:active={filter===f.id} aria-pressed={filter===f.id} onclick={()=>filter=f.id}>{f.label} <span>{f.n}</span></button>{/each}</nav><div class="search"><Search size={16}/><input aria-label="Abos und Fixkosten durchsuchen" placeholder="Anbieter suchen …" bind:value={query}/></div><select aria-label="Vertragskategorie" bind:value={group}><option value="">Alle Bereiche</option>{#each contractGroups as g}<option value={g}>{g}</option>{/each}</select></div>
   <div class="list" aria-live="polite">
    {#each shown as item}
     <article id={item.id} class:urgent={item.priority==='high'&&item.status!=='cancelled'} class:ended={item.status==='cancelled'}>
      <button class="row" aria-expanded={expanded===item.id} aria-controls={'details-'+item.id} onclick={()=>open(item)}>
       <span class="identity"><small>{item.group} · {contractStatusLabels[item.status]}</small><strong>{item.label}</strong><span class="summary">{item.summary}</span></span>
       <span class="cost"><strong>{item.cost}</strong>{#if item.timing}<small><CalendarClock size={13}/>{date(item.timing.date)} · {item.timing.label}</small>{/if}</span><ChevronDown size={19} class={expanded===item.id?'turned':''}/>
      </button>
      {#if expanded===item.id}<div id={'details-'+item.id} class="detail">
       <div class="next"><strong>Nächster Schritt</strong><p>{item.next_step}</p>{#if item.timing}<small>{item.timing.basis==='estimated'?'Termin aus bisherigem Rhythmus geschätzt; im Konto prüfen.':item.timing.basis==='review'?'Interner Prüftermin, keine bestätigte Vertragsfrist.':'Datum aus dem Beleg; ein Zahlungstermin ist keine Kündigungsfrist.'}</small>{/if}</div>
       {#if item.unknowns.length}<div class="questions"><strong>Noch offen</strong><ul>{#each item.unknowns as question}<li>{question}</li>{/each}</ul></div>{/if}
       <div class="evidence"><h2>Belege & Verlauf</h2>{#each item.evidence as e}<div class="proof"><div><small>{date(e.date)} · {e.kind==='mail'?'Mail':'Kontobewegung'}{!e.valid?' · Quelle erneut prüfen':''}</small><strong>{e.label}</strong><p>{e.note}</p></div>{#if e.kind==='mail'&&e.valid}<a href={e.href}><FileText size={15}/>Mail öffnen</a>{:else if e.kind==='bank'&&e.valid&&data.batch}<button aria-expanded={bank===e.id} onclick={()=>bank=bank===e.id?'':e.id}><FileText size={15}/>Buchung & Beleg</button>{/if}</div>{#if e.kind==='bank'&&e.valid&&bank===e.id&&data.batch}<div class="bank-detail"><HouseholdEntryEvidence id={e.id} batch={data.batch}/></div>{/if}{/each}</div>
       {#if item.help}<a class="help" href={item.help.url} target="_blank" rel="noopener noreferrer">{item.help.label}<ExternalLink size={13}/></a>{/if}
      </div>{/if}
     </article>
    {/each}
    {#if !shown.length}<p class="empty">Keine passenden Posten.</p>{/if}
   </div>
   <footer>Kosten und Zahlungstermine sind keine zugesagten Einsparungen. Hier wird keine Kündigung ausgelöst.</footer>
  {/if}
 </div>
</main>
<style>
 #folio-household.contracts .metrics button{background:var(--hh-bg);border:1px solid var(--hh-line)}#folio-household.contracts .controls button.active{background:var(--hh-text);color:var(--hh-bg)}#folio-household.contracts h1{font-size:32px;margin:4px 0 8px}#folio-household.contracts .detail p{margin:6px 0}#folio-household.contracts .row:hover{background:var(--hh-soft)}
 .contracts{min-height:100%;background:var(--hh-bg);color:var(--hh-text)}.content{max-width:1220px;margin:auto;padding:28px 32px 65px}.back{display:inline-flex;align-items:center;gap:7px;color:var(--hh-muted);font-size:13px;text-decoration:none;margin-bottom:25px}header{display:flex;justify-content:space-between;align-items:end;gap:20px}h1{font-size:32px;font-weight:650;letter-spacing:-.8px;margin:4px 0 8px}header p{color:var(--hh-muted);font-size:14px;margin:0}.eyebrow{font:11px ui-monospace,monospace!important;letter-spacing:1.5px}.asof{font-size:12px;color:var(--hh-muted);white-space:nowrap}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:28px 0 20px}.metrics button{display:grid;grid-template-columns:32px 1fr;gap:4px 12px;text-align:left;border:1px solid var(--hh-line);border-radius:12px;padding:18px;background:var(--hh-bg)}.metrics :global(svg){grid-row:span 2;color:var(--hh-blue);align-self:center}.metrics strong{font-size:25px;font-weight:650}.metrics span{font-size:12px;color:var(--hh-muted)}.coverage{border-bottom:1px solid var(--hh-line);padding:10px 0 18px;color:var(--hh-muted);font-size:12px;line-height:1.6}.coverage summary{cursor:pointer}.coverage ul{padding-left:18px}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0 14px;align-items:center}.controls nav{display:flex;gap:4px;flex-wrap:wrap;margin-right:auto}.controls button{padding:8px 10px;border-radius:7px;color:var(--hh-muted);font-size:12px}.controls button span{opacity:.7;margin-left:5px}.controls button.active{background:var(--hh-text);color:var(--hh-bg)}.search{display:flex;gap:7px;align-items:center;border:1px solid var(--hh-line);border-radius:8px;padding:8px 10px;color:var(--hh-muted)}input{background:transparent;border:0;min-width:0;width:140px;font:inherit;font-size:12px;color:var(--hh-text);outline:none}select{border:1px solid var(--hh-line);background:var(--hh-bg);color:var(--hh-text);padding:8px;border-radius:8px;font-size:12px}.list{border:1px solid var(--hh-line);border-radius:12px;overflow:hidden}article+article{border-top:1px solid var(--hh-line)}article{background:var(--hh-bg);scroll-margin-top:70px}article.urgent{border-left:3px solid #bd7786}article.ended{border-left:3px solid var(--hh-line)}.row{width:100%;display:grid;grid-template-columns:minmax(0,1fr) minmax(150px,260px) 22px;text-align:left;gap:22px;padding:20px 24px;align-items:center;background:transparent}.row:hover{background:var(--hh-soft)}.identity{display:flex;flex-direction:column;gap:6px}.identity small{font-size:11px;color:var(--hh-muted)}.identity>strong{font-size:17px;font-weight:620}.summary{font-size:13px;color:var(--hh-muted);line-height:1.5}.cost{text-align:right;display:flex;flex-direction:column;gap:9px}.cost strong{font-size:14px;font-weight:600;font-variant-numeric:tabular-nums}.cost small{font-size:11px;color:var(--hh-muted);display:flex;gap:4px;justify-content:end;align-items:center}.cost :global(svg){flex:none}.row :global(svg.turned){transform:rotate(180deg)}.detail{border-top:1px solid var(--hh-line);padding:22px 25px;background:var(--hh-soft);font-size:13px;line-height:1.65}.detail p{margin:6px 0}.next strong,.questions strong{font-size:12px;text-transform:uppercase;letter-spacing:.5px}.next small{color:var(--hh-muted);font-size:11px}.questions{margin:20px 0}.questions ul{padding-left:18px;margin:5px 0}.evidence h2{font-size:14px;margin:22px 0 5px}.proof{display:flex;justify-content:space-between;gap:22px;padding:14px 0;border-top:1px solid var(--hh-line)}.proof>div{min-width:0}.proof small{display:block;color:var(--hh-muted);font-size:11px}.proof strong{display:block;font-size:13px;margin-top:3px;overflow-wrap:anywhere}.proof p{font-size:12px;color:var(--hh-muted)}.proof a,.proof button{color:var(--hh-blue);font-size:12px;display:flex;align-items:center;gap:5px;white-space:nowrap;text-decoration:none;align-self:start;padding:5px}.bank-detail{padding:20px;border:1px solid var(--hh-line);border-radius:8px;background:var(--hh-bg)}.help{display:inline-flex;gap:6px;align-items:center;color:var(--hh-blue);font-size:12px;margin-top:15px}.warning{border-left:3px solid #bd7786;padding:12px;font-size:13px;background:var(--hh-soft)}footer,.empty{font-size:12px;color:var(--hh-muted);padding:20px 0}.empty{padding:25px}button{cursor:pointer}button:focus-visible,a:focus-visible{outline:2px solid var(--hh-blue);outline-offset:3px}
 @media(max-width:700px){.content{padding:20px 14px 45px}header{align-items:start;flex-direction:column;gap:9px}h1{font-size:27px}.metrics{grid-template-columns:repeat(2,1fr);gap:8px}.metrics button{padding:13px}.controls nav{width:100%}.controls{gap:8px}.search{flex:1}.row{grid-template-columns:minmax(0,1fr) 20px;gap:10px;padding:16px}.identity{grid-column:1}.row>:global(svg){grid-column:2;grid-row:1}.cost{grid-column:1;text-align:left;gap:5px}.cost small{justify-content:start}.detail{padding:18px 16px}.proof{flex-direction:column;gap:4px}.bank-detail{padding:10px}}
</style>
